; ---------------------------------------------------------------
; void __near__ game_igloo (void)
; ---------------------------------------------------------------

.segment	"BANK1"

.proc	_game_igloo: near

.segment	"BANK1"

;
; IGLOO_RESET_PLAYER_FLAGS_START_FRAME();
;
	lda     _player_flags
	and     #$FC
	sta     _player_flags
;
; pad1 = pad_poll(0); // read the first controller
;
	lda     #$00
	jsr     _pad_poll
	sta     _pad1
;
; pad1_new = get_pad_new(0);
;
	lda     #$00
	jsr     _get_pad_new
	sta     _pad1_new
;
; ppu_wait_nmi(); // wait till beginning of the frame
;
	jsr     _ppu_wait_nmi
;
; clear_vram_buffer();
;
	jsr     _clear_vram_buffer
;
; set_prg_bank(IGLOO_CODE_BANK);
;
	lda     #$01
	jsr     _set_prg_bank
;
; igloo_player_movement();
;
	jsr     _igloo_player_movement
;
; igloo_carassa_movement();
;
	jsr     _igloo_carassa_movement
;
; igloo_item_movement();
;
	jsr     _igloo_item_movement
;
; igloo_sprite_collisions();
;
	jsr     _igloo_sprite_collisions
;
; igloo_draw_sprites();
;
	jsr     _igloo_draw_sprites
;
; if (IGLOO_SCORE_CHANGED_THIS_FRAME) { igloo_update_score(); }
;
	lda     _player_flags
	and     #$01
	beq     L0959
	jsr     _igloo_update_score
;
; if (game_seconds_timer > 0 || game_frame_timer > 0) {
;
L0959:	lda     _enemy_limit
	bne     L095A
	lda     _lowest_enemy_index
	jeq     L095F
;
; --game_frame_timer;
;
L095A:	dec     _lowest_enemy_index
;
; if (game_frame_timer == 0) {
;
	bne     L095C
;
; if (game_seconds_timer == 0) {
;
	lda     _enemy_limit
;
; igloo_begin_new_round();
;
	jeq     _igloo_begin_new_round
;
; game_frame_timer = 60;
;
	lda     #$3C
	sta     _lowest_enemy_index
;
; --game_seconds_timer;
;
	dec     _enemy_limit
;
; igloo_update_time();
;
	jsr     _igloo_update_time
;
; --next_item_timer;
;
L095C:	dec     _index
;
; if (next_item_timer == 0) {
;
	jne     L0960
;
; next_item_timer = 32 + (rand8() & 0b11111);
;
	jsr     _rand8
	and     #$1F
	clc
	adc     #$20
	sta     _index
;
; calculate_next_igloo_item();
;
	jsr     _calculate_next_igloo_item
;
; for (x = 0; x < ONSCREEN_JUNK_MAXIMUM; ++x) {
;
	lda     #$00
	sta     _x
L095D:	lda     _x
	cmp     #$0C
	jcs     L0960
;
; if (!IS_ENEMY_ACTIVE(x)) {
;
	ldy     _x
	lda     _enemies_flags,y
	and     #$80
	jne     L095E
;
; temp0 = rand8();
;
	jsr     _rand8
	sta     _temp0
;
; enemies_type[x] = temp4;
;
	ldy     _x
	lda     _temp4
	sta     _enemies_type,y
;
; enemies_flags[x] = 0;
;
	ldy     _x
	lda     #$00
	sta     _enemies_flags,y
;
; ACTIVATE_ENEMY(x);
;
	ldy     _x
	lda     _enemies_flags,y
	ora     #$80
	sta     _enemies_flags,y
;
; enemies_x[x] = (temp0 & 0b01111111) + 64;
;
	lda     #<(_enemies_x)
	ldx     #>(_enemies_x)
	clc
	adc     _x
	bcc     L0520
	inx
L0520:	sta     ptr1
	stx     ptr1+1
	lda     _temp0
	and     #$7F
	clc
	adc     #$40
	ldy     #$00
	sta     (ptr1),y
;
; enemies_y[x] = IGLOO_BRIDGE_Y_CHAR; // minus whatever for the item's height? Maybe use a LUT for that
;
	ldy     _x
	lda     #$38
	sta     _enemies_y,y
;
; enemies_subpixel_y[x] = 0;
;
	ldy     _x
	lda     #$00
	sta     _enemies_actual_y,y
;
; enemies_timer[x] = 0;
;
	ldy     _x
	sta     _enemies_timer,y
;
; carassa_item_walk_index_queue[carassa_item_walk_queue_back] = x;
;
	lda     _old_y
	ldx     _old_y+1
	clc
	adc     _tile_clear_back
	bcc     L0957
	inx
L0957:	sta     ptr1
	stx     ptr1+1
	lda     _x
	ldy     #$00
	sta     (ptr1),y
;
; temp0 = enemies_x[x];
;
	ldy     _x
	lda     _enemies_x,y
	sta     _temp0
;
; temp0 -= ((igloot_hitbox_x_offset_lookup_table[temp4] + igloot_hitbox_width_lookup_table[temp4]) >> 1); // Half of the visible sprite width
;
	ldy     _temp4
	lda     _igloot_hitbox_x_offset_lookup_table,y
	sta     ptr1
	ldy     _temp4
	lda     _igloot_hitbox_width_lookup_table,y
	clc
	adc     ptr1
	ror     a
	eor     #$FF
	sec
	adc     _temp0
	sta     _temp0
;
; AsmSet1ByteAtMutPtrWithOffset(old_x, tile_clear_back, temp0);
;
	ldy     _tile_clear_back
	lda     _temp0
	sta     (_old_x),y
;
; ++carassa_item_walk_queue_back;
;
	inc     _tile_clear_back
;
; carassa_item_walk_queue_back &= 0b1111;
;
	lda     _tile_clear_back
	and     #$0F
	sta     _tile_clear_back
;
; temp0 = rand8() & 0b111;
;
	jsr     _rand8
	and     #$07
	sta     _temp0
;
; AsmSet2ByteFromMutPtrWithOffset(temp5, temp_mutablepointer, temp0);
;
	asl     a
	tay
	lda     (_temp_mutablepointer),y
	sta     _temp5
	iny
	lda     (_temp_mutablepointer),y
	sta     _temp5+1
;
; enemies_y_velocity_pixels[x] = high_byte(temp5);
;
	ldy     _x
	lda     _temp5+1
	sta     _enemies_extra,y
;
; enemies_y_velocity_subpixels[x] = low_byte(temp5);
;
	ldy     _x
	lda     _temp5
	sta     _enemies_extra2,y
;
; break;
;
	jmp     L0960
;
; for (x = 0; x < ONSCREEN_JUNK_MAXIMUM; ++x) {
;
L095E:	inc     _x
	jmp     L095D
;
; } else if (round_begin_timer > 0) {
;
L095F:	lda     _eject_R
	beq     L0960
;
; --round_begin_timer;
;
	dec     _eject_R
;
; if (round_begin_timer == 0) {
;
	bne     L0960
;
; game_seconds_timer = 30;
;
	lda     #$1E
	sta     _enemy_limit
;
; game_frame_timer = 60;
;
	lda     #$3C
	sta     _lowest_enemy_index
;
; igloo_clear_top_message();
;
	jsr     _igloo_clear_top_message
;
; igloo_clear_bottom_message();
;
	jsr     _igloo_clear_bottom_message
;
; if (pad1 & PAD_B) {
;
L0960:	lda     _pad1
	and     #$40
	cmp     #$00
;
; end_igloo();
;
	jne     _end_igloo
;
; }
;
	rts

.endproc

; ---------------------------------------------------------------
; void __near__ begin_igloo (void)
; ---------------------------------------------------------------

.segment	"CODE"

.proc	_begin_igloo: near

.segment	"CODE"

;
; pal_fade_to(4, 0);
;
	lda     #$04
	jsr     pusha
	lda     #$00
	jsr     _pal_fade_to
;
; ppu_off();
;
	jsr     _ppu_off
;
; clear_screen();
;
	jsr     _clear_screen
;
; clear_vram_buffer();
;
	jsr     _clear_vram_buffer
;
; oam_clear();
;
	jsr     _oam_clear
;
; set_prg_bank(5);
;
	lda     #$05
	jsr     _set_prg_bank
;
; temppointer = igloo_game_screen;
;
	lda     #<(_igloo_game_screen)
	ldx     #>(_igloo_game_screen)
	sta     _temppointer
	stx     _temppointer+1
;
; LZG_decode(temppointer, cmap);
;
	jsr     pushax
	lda     #<(_cmap)
	ldx     #>(_cmap)
	jsr     _LZG_decode
;
; vram_write(cmap, 32*32);
;
	lda     #<(_cmap)
	ldx     #>(_cmap)
	jsr     pushax
	ldx     #$04
	lda     #$00
	jsr     _vram_write
;
; memfill(cmap, 0, 32); // For character buffering later on when we want spaces
;
	jsr     decsp3
	lda     #<(_cmap)
	ldy     #$01
	sta     (sp),y
	iny
	lda     #>(_cmap)
	sta     (sp),y
	lda     #$00
	tay
	sta     (sp),y
	tax
	lda     #$20
	jsr     _memfill
;
; set_prg_bank(IGLOO_CODE_BANK);
;
	lda     #$01
	jsr     _set_prg_bank
;
; begin_igloo_sub();   
;
	jmp     _begin_igloo_sub

.endproc

; ---------------------------------------------------------------
