; ---------------------------------------------------------------

.segment	"BANK1"

.proc	_begin_igloo_sub: near

.segment	"BANK1"

;
; music_play(ICE_CREAM_MACHINE_SONG);
;
	lda     #$07
	jsr     _music_play
;
; game_mode = MODE_GAME;
;
	lda     #$01
	sta     _game_mode
;
; enemies_count = ONSCREEN_JUNK_MAXIMUM; // Used by extern'd functions
